// Workspace headless adapter; upstream evaluator and its arithmetic are unchanged.
#include <cstdint>
#include <cuda_runtime.h>
#include "rasterizer.h"
#include "scheduler.h"
#include "rasterizer_impl.h"
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <string>
#include <iostream>
#include <iomanip>
#include <algorithm>
#include <numeric>
#include <chrono>
#include <cmath>
#include <cstring>
#include <filesystem>
#include <stdexcept>
using Clock=std::chrono::steady_clock;
static void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct Buffer{char* p=nullptr;size_t size=0;char* get(size_t n){if(n>size){size_t free,total;ck(cudaMemGetInfo(&free,&total));size_t reserve=std::max<size_t>(2ull<<30,total*0.15);if(n>free||free-n<reserve)throw std::runtime_error("VRAM headroom guard");if(p)ck(cudaFree(p));ck(cudaMalloc(&p,n));size=n;}return p;}~Buffer(){if(p)cudaFree(p);}};
struct Data {int n;std::vector<float> xyz,sh,opacity,scale,rotation;};
Data load_model(const std::string& name){std::ifstream f(name,std::ios::binary);if(!f)throw std::runtime_error("model open");std::string line;std::getline(f,line);if(line!="ply")throw std::runtime_error("not PLY");int n=0;std::vector<std::string> fields;bool binary=false,vertex=false;while(std::getline(f,line)&&line!="end_header"){std::istringstream in(line);std::string k,a,b;in>>k>>a>>b;if(k=="format")binary=a=="binary_little_endian";if(k=="element"){vertex=a=="vertex";if(vertex)n=std::stoi(b);}if(k=="property"){if(!vertex||a!="float")throw std::runtime_error("unsupported PLY property");fields.push_back(b);}}if(!binary||n<1||n>10000000||fields.size()!=62)throw std::runtime_error("unsupported Gaussian PLY schema");std::map<std::string,int> ix;for(int j=0;j<(int)fields.size();j++)ix[fields[j]]=j;auto at=[&](const std::string&s){return ix.at(s);};std::vector<float> rows(size_t(n)*fields.size());f.read((char*)rows.data(),rows.size()*4);if(!f)throw std::runtime_error("truncated PLY");Data d;d.n=n;d.xyz.resize(n*3ull);d.sh.resize(n*48ull);d.opacity.resize(n);d.scale.resize(n*3ull);d.rotation.resize(n*4ull);for(int i=0;i<n;i++){auto r=rows.data()+size_t(i)*fields.size();for(int k=0;k<62;k++)if(!std::isfinite(r[k]))throw std::runtime_error("nonfinite model");for(int j=0;j<3;j++){d.xyz[i*3+j]=r[at(j==0?"x":j==1?"y":"z")];d.scale[i*3+j]=std::exp(r[at("scale_"+std::to_string(j))]);d.sh[i*48+j]=r[at("f_dc_"+std::to_string(j))];for(int k=1;k<16;k++)d.sh[i*48+k*3+j]=r[at("f_rest_"+std::to_string(j*15+k-1))];}d.opacity[i]=1.f/(1.f+std::exp(-r[at("opacity")]));float norm=0;for(int j=0;j<4;j++){float a=r[at("rot_"+std::to_string(j))];norm+=a*a;}norm=std::sqrt(norm);if(!(norm>0))throw std::runtime_error("bad quaternion");for(int j=0;j<4;j++)d.rotation[i*4+j]=r[at("rot_"+std::to_string(j))]/norm;}
return d;}
struct Camera{float view[16],proj[16],pos[3],tanx,tany;};
std::vector<Camera> load_cameras(const std::string& name){std::ifstream f(name,std::ios::binary);uint32_t n;f.read((char*)&n,4);if(!f||n<3||n>10000)throw std::runtime_error("bad cameras");std::vector<Camera> c(n);static_assert(sizeof(Camera)==37*4);f.read((char*)c.data(),n*sizeof(Camera));if(!f)throw std::runtime_error("truncated cameras");return c;}
static uint64_t hash64(const void* p,size_t bytes){auto b=(const unsigned char*)p;uint64_t h=1469598103934665603ull;for(size_t i=0;i<bytes;i++)h=(h^b[i])*1099511628211ull;return h;}
static float* upload(Buffer& b,const std::vector<float>& x){float* p=(float*)b.get(x.size()*4);ck(cudaMemcpy(p,x.data(),x.size()*4,cudaMemcpyHostToDevice));return p;}
int main(int argc,char**argv){try{
if(argc!=10)throw std::runtime_error("Usage: native scene_dir W H camera_start frame_count output_dir warmup_frames");schedule_config.policy=std::stoi(argv[8]);schedule_config.executor=std::stoi(argv[9]);std::string dir=argv[1];int W=std::stoi(argv[2]),H=std::stoi(argv[3]),start=std::stoi(argv[4]),frames=std::stoi(argv[5]),warm=std::stoi(argv[7]);std::string out=argv[6];if(W<1||H<1||W>2560||H>1440||frames<1||frames>4096||warm<0||warm>4096)throw std::runtime_error("invalid bounds");std::filesystem::create_directories(out);Data d=load_model(dir+"/point_cloud/iteration_30000/point_cloud.ply");auto cams=load_cameras(dir+"/camera_replay.bin");Buffer bx,bs,bo,bc,br,bg,bcam,bout,geom,bin,img;float* xyz=upload(bx,d.xyz),*sh=upload(bs,d.sh),*opacity=upload(bo,d.opacity),*scale=upload(bc,d.scale),*rot=upload(br,d.rotation);std::vector<float> bgv(3,0);float* background=upload(bg,bgv);float* output=(float*)bout.get(size_t(W)*H*12);float* cam=(float*)bcam.get(sizeof(Camera));cudaEvent_t begin,end;ck(cudaEventCreate(&begin));ck(cudaEventCreate(&end));std::ofstream csv(out+"/frames.csv");csv<<"frame,camera,gpu_span_ms,cpu_result_ready_ms,instances,color_hash,finite,preprocess_ms,scan_ms,sort_ms,build_ms,render_ms,cpu_plan_ms,bundles,cap_hits\n";std::vector<float> host(size_t(W)*H*3);std::vector<uint32_t> reference;double firstms=0;for(int frame=-warm;frame<frames;frame++){int ci=((start+std::max(frame,0))%int(cams.size())+cams.size())%cams.size();auto a=Clock::now();ck(cudaEventRecord(begin));ck(cudaMemcpy(cam,&cams[ci],sizeof(Camera),cudaMemcpyHostToDevice));int instances=CudaRasterizer::Rasterizer::forward([&](size_t n){return geom.get(n);},[&](size_t n){return bin.get(n);},[&](size_t n){return img.get(n);},d.n,3,16,background,W,H,xyz,sh,nullptr,opacity,scale,1.f,rot,nullptr,cam,cam+16,cam+32,cams[ci].tanx,cams[ci].tany,false,output,nullptr,false);ck(cudaGetLastError());ck(cudaEventRecord(end));ck(cudaEventSynchronize(end));auto b=Clock::now();schedule_times();float ms;ck(cudaEventElapsedTime(&ms,begin,end));if(frame>=0){ck(cudaMemcpy(host.data(),output,host.size()*4,cudaMemcpyDeviceToHost));bool finite=std::all_of(host.begin(),host.end(),[](float v){return std::isfinite(v);});uint64_t hash=hash64(host.data(),host.size()*4);csv<<frame<<','<<ci<<','<<std::setprecision(9)<<ms<<','<<std::chrono::duration<double,std::milli>(b-a).count()<<','<<instances<<','<<hash<<','<<finite<<','<<schedule_stats.preprocess_ms<<','<<schedule_stats.scan_ms<<','<<schedule_stats.sort_ms<<','<<schedule_stats.build_ms<<','<<schedule_stats.render_ms<<','<<schedule_stats.cpu_plan_ms<<','<<schedule_stats.bundles<<','<<schedule_stats.cap_hits<<'\n';if(!finite)throw std::runtime_error("nonfinite render");if(frame==0){firstms=ms;std::ofstream f(out+"/color.raw",std::ios::binary);f.write((char*)host.data(),host.size()*4);char* ptr=img.p;auto state=CudaRasterizer::ImageState::fromChunk(ptr,size_t(W)*H);std::vector<float> alpha(size_t(W)*H);std::vector<uint32_t> contrib(size_t(W)*H);ck(cudaMemcpy(alpha.data(),state.accum_alpha,alpha.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(contrib.data(),state.n_contrib,contrib.size()*4,cudaMemcpyDeviceToHost));std::ofstream fa(out+"/final_T.raw",std::ios::binary);fa.write((char*)alpha.data(),alpha.size()*4);std::ofstream fn(out+"/n_contrib.raw",std::ios::binary);fn.write((char*)contrib.data(),contrib.size()*4);std::ofstream ppm(out+"/preview.ppm",std::ios::binary);ppm<<"P6\n"<<W<<' '<<H<<"\n255\n";for(size_t i=0;i<size_t(W)*H;i++)for(int c=0;c<3;c++){unsigned char v=static_cast<unsigned char>(std::clamp(host[c*size_t(W)*H+i],0.f,1.f)*255.f);ppm.write((char*)&v,1);}}}if(ms>200)throw std::runtime_error("frame span >200ms; stop scaling");}
std::cout<<"{\"gaussians\":"<<d.n<<",\"cameras\":"<<cams.size()<<",\"frames\":"<<frames<<",\"width\":"<<W<<",\"height\":"<<H<<",\"first_measured_gpu_span_ms\":"<<firstms<<",\"geometry_bytes\":"<<geom.size<<",\"binning_bytes\":"<<bin.size<<",\"image_bytes\":"<<img.size<<"}\n";ck(cudaEventDestroy(begin));ck(cudaEventDestroy(end));return 0;
}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
